css:
*{box-sizing:border-box}
body{margin:0;background:#FAF8F3;color:#1B1A17;font-family:'Palatino Linotype','Book Antiqua',Palatino,'Iowan Old Style',Georgia,serif;font-size:17px;line-height:1.6;-webkit-font-smoothing:antialiased}
a{color:inherit}
.mono{font-family:ui-monospace,'SFMono-Regular',Menlo,Consolas,monospace}
.wrap{max-width:820px;margin:0 auto;padding:clamp(40px,6vw,80px) clamp(22px,5vw,48px)}
.filing{display:flex;align-items:baseline;justify-content:space-between;gap:16px;font-family:ui-monospace,'SFMono-Regular',Menlo,monospace;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#928D80;border-bottom:1px solid #D9D3C6;padding-bottom:10px;margin-bottom:clamp(26px,4vw,44px)}
.filing .ref{color:var(--jj-accent)}
.masthead{border-top:2px solid #1B1A17;padding-top:22px}
.masthead h1{font-weight:600;font-size:clamp(2.4rem,7vw,4.2rem);line-height:1.02;letter-spacing:-.01em;margin:0}
.masthead .kicker{font-style:italic;font-size:clamp(1rem,2.2vw,1.25rem);color:#6C685E;margin-top:12px}
section{margin-top:clamp(44px,7vw,72px)}
.sectitle{display:flex;align-items:center;gap:16px;font-family:ui-monospace,'SFMono-Regular',Menlo,monospace;font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:#928D80;margin:0 0 clamp(20px,3vw,32px)}
.sectitle::after{content:'';flex:1;height:1px;background:#D9D3C6}
.panel{border:1px solid #D9D3C6;background:#fff;padding:clamp(20px,3vw,32px)}
.index-list{list-style:none;margin:0;padding:0}
.item{display:block;border-top:1px solid #D9D3C6;padding:clamp(16px,2.4vw,24px) 0;transition:padding-left .3s ease}
.item:first-child{border-top:none}
.item:hover{padding-left:10px}
.item .row{display:flex;align-items:baseline;justify-content:space-between;gap:20px}
.item h3{font-weight:600;font-size:clamp(1.3rem,3vw,2rem);line-height:1.1;letter-spacing:-.01em;margin:0}
.item:hover h3{color:var(--jj-accent)}
.item .folio{font-family:ui-monospace,'SFMono-Regular',Menlo,monospace;font-size:11px;letter-spacing:.14em;color:#928D80;white-space:nowrap}
.item .read{display:inline-block;margin-top:8px;font-family:ui-monospace,'SFMono-Regular',Menlo,monospace;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#928D80}
.item:hover .read{color:var(--jj-accent)}
.empty{color:#928D80;font-style:italic}
.entry .back{display:inline-block;font-family:ui-monospace,'SFMono-Regular',Menlo,monospace;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#928D80;border-bottom:1px solid #B7AF9E;padding-bottom:2px;margin-bottom:clamp(26px,4vw,44px);transition:color .25s,border-color .25s}
.entry .back:hover{color:var(--jj-accent);border-color:var(--jj-accent)}
.entry-title{font-weight:600;font-size:clamp(2.1rem,6vw,3.6rem);line-height:1.05;letter-spacing:-.015em;margin:0 0 clamp(28px,5vw,48px);padding-bottom:clamp(20px,3vw,32px);border-bottom:2px solid #1B1A17}
.fields{max-width:66ch}
.fld{margin:0 0 clamp(22px,3vw,34px)}
.fld-label{font-family:ui-monospace,'SFMono-Regular',Menlo,monospace;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#928D80;margin-bottom:8px}
.fld a{color:var(--jj-accent);text-decoration:none;border-bottom:1px solid #B7AF9E}
.fld a:hover{border-color:var(--jj-accent)}
.rt{font-size:clamp(1rem,1.4vw,1.15rem);line-height:1.72;color:#2a2823}
.rt h1,.rt h2,.rt h3{font-weight:600;letter-spacing:-.01em;line-height:1.15;margin:1.4em 0 .5em}
.rt p{margin:0 0 1em}
.rt a{color:var(--jj-accent)}
.rt blockquote{border-left:3px solid var(--jj-accent);margin:1.3em 0;padding:.2em 0 .2em 20px;font-style:italic;color:#4a463e}
.rt code{font-family:ui-monospace,'SFMono-Regular',Menlo,monospace;font-size:.88em;background:#F0ECE2;padding:1px 6px;border-radius:3px}
.rt img,.img{max-width:100%;border:1px solid #D9D3C6}.img{max-height:440px}
.swatch{display:inline-block;width:16px;height:16px;border-radius:3px;vertical-align:middle;border:1px solid #B7AF9E}
ul{padding-left:20px}li{margin:5px 0}
footer{border-top:1px solid #D9D3C6;margin-top:clamp(56px,8vw,90px);padding:22px clamp(22px,5vw,48px);color:#928D80;font-family:ui-monospace,'SFMono-Regular',Menlo,monospace;font-size:11px;letter-spacing:.14em;text-transform:uppercase;text-align:center}
